{
    var compileItems = p.FindChildrenRecursive<Item>().Where(i => i.Name == "Compile");
    Console.WriteLine($"\nServices compile items:");
    foreach (var c in compileItems.Take(20))
        Console.WriteLine($"  {c.Text}");
}

Console.WriteLine("\n=== CORE.CSPROJ ERRORS ===");
